get_customer_portal.code:
use WebCommander\Sdk\Resources\Settings\CustomerPortal\CustomerPortal;

$response = CustomerPortal::getCustomerPortal($client);

echo 'registration: ', $response->map['customer_portal']['registration']['enabled'] ? 'open' : 'closed', PHP_EOL;
foreach ($response->map['group_meta'] as $section => $meta) {
    echo $section, $meta['writable'] ? ' (writable)' : ' (read-only)', PHP_EOL;
}

patch_customer_portal.code:
use WebCommander\Sdk\Resources\Settings\CustomerPortal\CustomerPortal;

$response = CustomerPortal::patchCustomerPortal($client, [
    'customer_portal' => [
        'login' => ['registration_link' => false],
        'sso' => ['azure_ad' => ['data_mapping' => ['city' => 'city']]],
    ],
]);

$settings = $response->map['customer_portal'];
echo $settings['login']['registration_link'] ? 'true' : 'false', PHP_EOL;
echo $settings['sso']['azure_ad']['data_mapping']['city'], PHP_EOL;

get_customer_portal_section.code:
use WebCommander\Sdk\Resources\Settings\CustomerPortal\CustomerPortal;

$response = CustomerPortal::getCustomerPortalSection($client, 'login');

$login = $response->map['login'];
echo 'password recovery: ', $login['password_recovery'] ? 'on' : 'off', PHP_EOL;
echo 'captcha after ', $login['captcha']['fail_count'], ' failed attempts', PHP_EOL;
